/**
 * U.S. map shaded by how often a unit was stopped in each state. The shapes
 * are U.S. Census boundaries in an Albers projection (Alaska and Hawaii
 * repositioned), generated by scripts/build-us-map.mjs. The SVG scales to
 * the width of its panel. Counts are printed on the map and listed below it,
 * so the shading is never the only signal.
 */

import { el, formatDate, formatNumber, svgEl } from './dom';
import { US_MAP_SIZE, US_STATES } from './usPaths';

export interface StateCount {
  readonly state: string;
  readonly count: number;
  readonly lastDate: string | null;
}

/** Count items per state code; codes outside the map (Canada, Mexico, PR) are kept. */
export function stateCounts(
  items: ReadonlyArray<{ state: string | null; date: string | null }>,
): StateCount[] {
  const map = new Map<string, { count: number; lastDate: string | null }>();
  for (const item of items) {
    if (!item.state) continue;
    const entry = map.get(item.state) ?? { count: 0, lastDate: null };
    entry.count += 1;
    if (item.date && (!entry.lastDate || item.date > entry.lastDate)) entry.lastDate = item.date;
    map.set(item.state, entry);
  }
  return [...map.entries()].map(([state, value]) => ({ state, ...value }));
}

/** Small states whose label would collide with neighbours get a leader to open water. */
const SMALL_LABELS: Readonly<Record<string, readonly [number, number]>> = {
  VT: [858, 118], NH: [884, 138], MA: [905, 172], RI: [900, 196], CT: [885, 210],
  NJ: [872, 258], DE: [868, 292], MD: [862, 322], DC: [850, 344],
};

function tooltip(name: string, entry: StateCount | undefined, noun: string): string {
  if (!entry) return name + ': none';
  return (
    name + ': ' + formatNumber(entry.count) + ' ' + noun + (entry.count === 1 ? '' : 's') +
    (entry.lastDate ? ', last ' + formatDate(entry.lastDate) : '')
  );
}

export function renderStateMap(counts: readonly StateCount[], noun = 'inspection'): HTMLElement | null {
  if (counts.length === 0) return null;
  const byState = new Map(counts.map((c) => [c.state, c]));
  const max = Math.max(...counts.map((c) => c.count));
  const known = new Set(US_STATES.map((s) => s.code));

  const svg = svgEl('svg', {
    class: 'usmap__svg',
    viewBox: '0 0 ' + US_MAP_SIZE.width + ' ' + US_MAP_SIZE.height,
    role: 'img',
    'aria-label':
      'Map of the United States shaded by inspections per state: ' +
      [...counts].sort((a, b) => b.count - a.count).map((c) => c.state + ' ' + c.count).join(', '),
  });
  const shapes = svgEl('g', { class: 'usmap__shapes' });
  const labels = svgEl('g', { class: 'usmap__labels', 'aria-hidden': 'true' });

  for (const state of US_STATES) {
    const entry = byState.get(state.code);
    const level = entry ? Math.max(1, Math.ceil((entry.count / max) * 4)) : 0;
    const shape = svgEl('path', { class: 'usmap__state', d: state.d, 'data-level': String(level) });
    shape.append(svgEl('title', {}, tooltip(state.name, entry, noun)));
    shapes.append(shape);

    if (!entry) continue;
    const small = SMALL_LABELS[state.code];
    const [x, y] = small ?? [state.cx, state.cy];
    if (small) {
      labels.append(svgEl('line', { class: 'usmap__leader', x1: String(state.cx), y1: String(state.cy), x2: String(x - 4), y2: String(y) }));
    }
    labels.append(
      svgEl(
        'text',
        { class: 'usmap__label', 'data-level': String(level), x: String(x), y: String(y), 'text-anchor': small ? 'start' : 'middle' },
        state.code + ' ' + entry.count,
      ),
    );
  }
  svg.append(shapes, labels);

  const outside = counts.filter((c) => !known.has(c.state)).sort((a, b) => b.count - a.count);
  const ranked = [...counts].filter((c) => known.has(c.state)).sort((a, b) => b.count - a.count || (b.lastDate ?? '').localeCompare(a.lastDate ?? ''));

  return el(
    'figure',
    { class: 'usmap' },
    svg,
    el(
      'figcaption',
      { class: 'usmap__caption' },
      el(
        'ul',
        { class: 'chips__list' },
        ...ranked.slice(0, 10).map((c) =>
          el(
            'li',
            { class: 'chip', title: c.lastDate ? 'Last ' + formatDate(c.lastDate) : undefined },
            el('span', { class: 'chip__label' }, c.state),
            el('span', { class: 'chip__count' }, '×' + formatNumber(c.count)),
          ),
        ),
        ranked.length > 10 ? el('li', { class: 'chip chip--more' }, '+' + (ranked.length - 10) + ' more') : null,
      ),
      outside.length > 0
        ? el('p', { class: 'usmap__outside' }, 'Outside the 50 states: ', outside.map((c) => c.state + ' ' + formatNumber(c.count)).join(' · '))
        : null,
    ),
  );
}
